namespace FireURQ.Porter.Translation;

public static class CSharpObjectRuntime
{
    public const string Source = """
// <auto-generated />
#nullable enable
namespace FireURQ.Runtime
{
    // Reference-count portion of the Delphi interface contract.
    // QueryInterface is not implemented yet.
    public interface IInterface
    {
        int _AddRef();
        int _Release();
    }

    public class TInterfacedObject : TObject, IInterface
    {
        int IInterface._AddRef() => _AddRef();
        int IInterface._Release() => _Release();

        protected int FRefCount;

        public int RefCount =>
            global::System.Threading.Volatile.Read(ref FRefCount);

        // Delphi also permits protected-member access within its unit.
        // The generated units currently share one C# assembly.
        protected internal int _AddRef()
        {
            return global::System.Threading.Interlocked.Increment(
                ref FRefCount);
        }

        protected internal int _Release()
        {
            int remaining =
                global::System.Threading.Interlocked.Decrement(
                    ref FRefCount);
            if (remaining == 0)
                Destroy();
            return remaining;
        }
    }

    public static class DelphiStorage
    {
        public static void SetChar(ref string value, int index, char replacement)
        {
            char[] characters = value.ToCharArray();
            characters[index - 1] = replacement;
            value = new string(characters);
        }

        public static void Delete(ref string value, int index, int count)
        {
            if (string.IsNullOrEmpty(value) || index < 1 || index > value.Length || count <= 0)
                return;
            int start = index - 1;
            value = value.Remove(start, global::System.Math.Min(count, value.Length - start));
        }

        public static void SetLength(ref string value, int length)
        {
            if (length < 0)
                throw new global::System.ArgumentOutOfRangeException(nameof(length));
            string previous = value ?? string.Empty;
            value = length <= previous.Length
                ? previous.Substring(0, length)
                : previous.PadRight(length, '\0');
        }

        public static void SetLength<T>(ref T[] value, int length)
        {
            if (length == 0)
            {
                value = null!;
                return;
            }

            // Delphi SetLength detaches shared dynamic array storage, even at equal length.
            var resized = new T[length];
            if (value is not null)
                global::System.Array.Copy(value, resized, global::System.Math.Min(value.Length, length));
            value = resized;
        }
    }

    public class TObject
    {
        private int __fireurqDestructorDepth;

        // Generated constructors call inherited Create on an already allocated CLR instance.
        protected void Create() { }

        public static void FreeAndNil<T>(ref T value) where T : TObject
        {
            T previous = value;
            value = null!;
            Free(previous);
        }

        protected global::System.IDisposable __FireUrqEnterDestructor()
        {
            __fireurqDestructorDepth++;
            return new DestructorScope(this);
        }

        public virtual void Destroy()
        {
            using var scope = __FireUrqEnterDestructor();
        }

        public void Free()
        {
            Free(this);
        }

        public static void Free(TObject? value)
        {
            if (value is not null)
                value.Destroy();
        }

        protected internal virtual void FreeInstance()
        {
            // Managed object storage is reclaimed by the CLR.
            // Descendants release their owned resources in Destroy.
        }

        private sealed class DestructorScope : global::System.IDisposable
        {
            private TObject? owner;

            public DestructorScope(TObject value)
            {
                owner = value;
            }

            public void Dispose()
            {
                TObject? value = owner;
                if (value is null)
                    return;

                owner = null;
                value.__fireurqDestructorDepth--;
                if (value.__fireurqDestructorDepth == 0)
                    value.FreeInstance();
            }
        }
    }
}
""";
}